import org.junit.jupiter.api.Test;
import java.util.Arrays;
import java.util.Comparator;
import static org.junit.jupiter.api.Assertions.*;

public class MergeSortTest {

    @Test
    void testMergeSort_nullArray() {
        assertThrows(NullPointerException.class, () -> MergeSort.mergeSort(null));
        assertThrows(NullPointerException.class, () -> MergeSort.mergeSort(null, null));

    }

    @Test
    void testMergeSort_emptyArray() {
        Integer[] arr = {};
        Integer[] sortedArr = MergeSort.mergeSort(arr);
        assertArrayEquals(arr, sortedArr);

        String[] arr2 = {};
        String[] sortedArr2 = MergeSort.mergeSort(arr2);
        assertArrayEquals(arr2, sortedArr2);
    }

    @Test
    void testMergeSort_singleElementArray() {
        Integer[] arr = {5};
        Integer[] sortedArr = MergeSort.mergeSort(arr);
        assertArrayEquals(arr, sortedArr);

        String[] arr2 = {"a"};
        String[] sortedArr2 = MergeSort.mergeSort(arr2);
        assertArrayEquals(arr2, sortedArr2);
    }

    @Test
    void testMergeSort_alreadySortedArray() {
        Integer[] arr = {1, 2, 3, 4, 5};
        Integer[] sortedArr = MergeSort.mergeSort(arr);
        assertArrayEquals(arr, sortedArr);

        String[] arr2 = {"a", "b", "c", "d"};
        String[] sortedArr2 = MergeSort.mergeSort(arr2);
        assertArrayEquals(arr2, sortedArr2);
    }

    @Test
    void testMergeSort_unsortedArray() {
        Integer[] arr = {5, 2, 8, 1, 9, 4};
        Integer[] expected = {1, 2, 4, 5, 8, 9};
        Integer[] sortedArr = MergeSort.mergeSort(arr);
        assertArrayEquals(expected, sortedArr);

        String[] arr2 = {"e", "c", "a", "d", "b"};
        String[] expected2 = {"a", "b", "c", "d", "e"};
        String[] sortedArr2 = MergeSort.mergeSort(arr2);
        assertArrayEquals(expected2, sortedArr2);
    }

    @Test
    void testMergeSort_withComparator() {
        Integer[] arr = {5, 2, 8, 1, 9, 4};
        Integer[] expected = {9, 8, 5, 4, 2, 1};
        Integer[] sortedArr = MergeSort.mergeSort(arr, Comparator.reverseOrder());
        assertArrayEquals(expected, sortedArr);

        String[] arr2 = {"a", "b", "c", "d"};
        String[] expected2 = {"d", "c", "b", "a"};
        String[] sortedArr2 = MergeSort.mergeSort(arr2, Comparator.reverseOrder());
        assertArrayEquals(expected2, sortedArr2);
    }

    @Test
    void testMergeSort_withCustomObjects() {
        Person[] people = {
                new Person("Bob", 30),
                new Person("Alice", 25),
                new Person("Charlie", 35)
        };

        Person[] expectedByAge = {
                new Person("Alice", 25),
                new Person("Bob", 30),
                new Person("Charlie", 35)
        };

        Person[] expectedByName = {
                new Person("Alice", 25),
                new Person("Bob", 30),
                new Person("Charlie", 35)
        };


        Person[] sortedByAge = MergeSort.mergeSort(people, Comparator.comparingInt(Person::getAge));
        assertArrayEquals(expectedByAge, sortedByAge);

        Person[] sortedByName = MergeSort.mergeSort(people, Comparator.comparing(Person::getName));
        assertArrayEquals(expectedByName, sortedByName);


    }


    static class Person {
        String name;
        int age;

        Person(String name, int age) {
            this.name = name;
            this.age = age;
        }

        public String getName() { return name; }
        public int getAge() { return age; }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Person person = (Person) obj;
            return age == person.age && name.equals(person.name);
        }
    }
}
